static dmg_snapshot* load(dmg_engine* e,const char* path){FILE* f=fopen(path,"rb");CHECK(f);CHECK(!fseek(f,0,SEEK_END));long n=ftell(f);CHECK(n>0);rewind(f);unsigned char* p=malloc((size_t)n);CHECK(p);CHECK(fread(p,1,(size_t)n,f)==(size_t)n);fclose(f);dmg_snapshot* s=NULL;dmg_error err={0};dmg_open_options o={sizeof(o),DMG_ABI_VERSION,(uint64_t)n,"test","one",NULL};dmg_status x=dmg_snapshot_open_copy_in(e,p,(uint64_t)n,&o,&s,&err);free(p);if(x!=DMG_OK)fprintf(stderr,"open status %u %s\n",x,err.message);CHECK(x==DMG_OK&&s);return s;}
static void query(dmg_engine* e,dmg_snapshot* s,const char* name,const char* mode,const char* values,const char* extra,unsigned count){
 char j[32768];int z=snprintf(j,sizeof(j),"{\"schema_version\":1,\"relation\":\"method_defs\",\"where\":{\"name\":\"%s\",\"opcodes\":{\"mode\":\"%s\",\"values\":[%s],\"negative_wildcards\":true%s}},\"intent\":\"enumerate\",\"required_capabilities\":[\"opcode_sequence\"]}",name,mode,values,extra);CHECK(z>0&&(size_t)z<sizeof(j));dmg_query* q=NULL;dmg_error err={0};dmg_status st=dmg_query_compile_json(e,(const uint8_t*)j,(uint64_t)strlen(j),&q,&err);if(st!=DMG_OK)fprintf(stderr,"compile %u %s %s\n",st,err.message,j);CHECK(st==DMG_OK&&q);dmg_query_info qi={0};CHECK(dmg_query_get_info(q,&qi)==DMG_OK);CHECK(qi.query_id&&strncmp(qi.query_id,"query:v23:",10)==0);CHECK((qi.required_capabilities&0x80000000u)!=0);CHECK((qi.demand_mask&512u)!=0);dmg_result* r=NULL;st=dmg_query_execute(s,q,&r,&err);if(st!=DMG_OK)fprintf(stderr,"execute %u %s\n",st,err.message);CHECK(st==DMG_OK&&r);dmg_result_info ri={0};CHECK(dmg_result_get_info(r,&ri)==DMG_OK);if(ri.candidates_count!=count)fprintf(stderr,"%s %s [%s] got %u expected %u status %u\n",name,mode,values,ri.candidates_count,count,ri.execution_status);CHECK(ri.execution_status==DMG_OK&&ri.candidates_count==count);dmg_result_release(r);dmg_query_release(q);
}
static void fails(dmg_engine* e,const char* j,dmg_status expected){dmg_query* q=NULL;dmg_error err={0};dmg_status st=dmg_query_compile_json(e,(const uint8_t*)j,strlen(j),&q,&err);if(st!=expected)fprintf(stderr,"bad compile status %u expected %u %s\n",st,expected,err.message);CHECK(st==expected&&!q);}
